                <input type="text" class="form-control @ValidationClass(Entry.Company)"
                       @bind="Entry.Company" @bind:event="oninput" placeholder="Company name" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input type="text" class="form-control @ValidationClass(Entry.Title)"
                       @bind="Entry.Title" @bind:event="oninput" placeholder="Job title" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control @(ShowValidation && !Entry.StartDate.HasValue ? "is-invalid" : "")"
