@using sv_f2ec9f5cdc234ccf89c46c1cb26694a6.Models

<h4 class="mb-4">Personal Information</h4>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger">@_errorMessage</div>
}

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input type="text" class="form-control @ValidationClass(Model.FullName)"
               @bind="Model.FullName" @bind:event="oninput" placeholder="Enter your full name" />
        @if (_showValidation && string.IsNullOrWhiteSpace(Model.FullName))
        {
            <div class="invalid-feedback d-block">Full name is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Email Address <span class="text-danger">*</span></label>
        <input type="email" class="form-control @ValidationClass(Model.Email)"
               @bind="Model.Email" @bind:event="oninput" placeholder="you@example.com" />
        @if (_showValidation && string.IsNullOrWhiteSpace(Model.Email))
        {
            <div class="invalid-feedback d-block">Email is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone Number <span class="text-danger">*</span></label>
        <input type="tel" class="form-control @ValidationClass(Model.Phone)"
               @bind="Model.Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
        @if (_showValidation && string.IsNullOrWhiteSpace(Model.Phone))
        {
            <div class="invalid-feedback d-block">Phone number is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input type="text" class="form-control @ValidationClass(Model.Address)"
               @bind="Model.Address" @bind:event="oninput" placeholder="Street address, city, state" />
        @if (_showValidation && string.IsNullOrWhiteSpace(Model.Address))
        {
            <div class="invalid-feedback d-block">Address is required.</div>
        }
    </div>
</div>

<div class="d-flex justify-content-end mt-4">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@_isValidating">
        @if (_isValidating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <text>Validating…</text>
        }
        else
        {
            <text>Next</text>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private bool _showValidation;
    private bool _isValidating;
    private string? _errorMessage;

    private async Task HandleNext()
    {
        _showValidation = true;
        _errorMessage = null;

        if (!Model.IsValid())
            return;

        _isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!emailValid)
            {
                _errorMessage = "The email address could not be validated. Please check and try again.";
                return;
            }

            await OnNext.InvokeAsync();
        }
        finally
        {
            _isValidating = false;
        }
    }

    private string ValidationClass(string value) =>
        _showValidation && string.IsNullOrWhiteSpace(value) ? "is-invalid" : "";
}

@using sv_f2ec9f5cdc234ccf89c46c1cb26694a6.Models

<h4 class="mb-4">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryForm Entry="Entries[index]"
                   Index="index"
                   ShowRemove="Entries.Count > 1"
                   ShowValidation="_showValidation"
                   OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn btn-outline-secondary mb-4" @onclick="AddEntry">
    + Add Another Position
</button>

@if (_showValidation && !AllEntriesValid())
{
    <div class="alert alert-danger">
        Please fill in all required fields (company, title, and start date) for each position.
    </div>
}

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private bool _showValidation;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private bool AllEntriesValid() => Entries.All(e => e.IsValid());

    private async Task HandleNext()
    {
        _showValidation = true;

        if (!AllEntriesValid())
            return;

        await OnNext.InvokeAsync();
    }
}

@using sv_f2ec9f5cdc234ccf89c46c1cb26694a6.Models

<h4 class="mb-4">References</h4>

<p class="text-muted mb-3">Please provide 2–3 professional references.</p>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceForm Reference="References[index]"
                   Index="index"
                   ShowRemove="References.Count > 1"
                   ShowValidation="_showValidation"
                   OnRemove="() => RemoveReference(index)" />
}

@if (References.Count < 3)
{
    <button type="button" class="btn btn-outline-secondary mb-4" @onclick="AddReference">
        + Add Reference
    </button>
}

@if (_showValidation && !AllReferencesValid())
{
    <div class="alert alert-danger">
        Please fill in all required fields for each reference.
    </div>
}

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private bool _showValidation;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 1)
        {
            References.RemoveAt(index);
        }
    }

    private bool AllReferencesValid() => References.All(r => r.IsValid());

    private async Task HandleNext()
    {
        _showValidation = true;

        if (!AllReferencesValid())
            return;

        await OnNext.InvokeAsync();
    }
}

@using sv_f2ec9f5cdc234ccf89c46c1cb26694a6.Models

<h4 class="mb-4">Review Your Application</h4>

@if (_submitted)
{
    <div class="alert alert-success text-center py-4">
        <h5 class="alert-heading mb-2">🎉 Application Submitted!</h5>
        <p class="mb-0">Your application has been received. Your confirmation number is:</p>
        <p class="display-6 fw-bold mb-0">@_applicationId</p>
    </div>
}
else
{
    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    <!-- Personal Info -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6"><strong>Name:</strong> @Personal.FullName</div>
                <div class="col-md-6"><strong>Email:</strong> @Personal.Email</div>
                <div class="col-md-6"><strong>Phone:</strong> @Personal.Phone</div>
                <div class="col-md-6"><strong>Address:</strong> @Personal.Address</div>
            </div>
        </div>
    </div>

    <!-- Work History -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var entry in WorkEntries)
            {
                <div class="mb-3 pb-3 border-bottom last-no-border">
                    <div class="fw-semibold">@entry.Title at @entry.Company</div>
                    <div class="text-muted small">
                        @entry.StartDate?.ToString("MMM yyyy")
                        – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <div class="mt-1">@entry.Description</div>
                    }
                </div>
            }
        </div>
    </div>

    <!-- References -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var r in References)
            {
                <div class="mb-2">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />
                    <span class="text-muted">@r.Email · @r.Phone</span>
                </div>
            }
        </div>
    </div>

    <!-- Cover Letter -->
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Cover Letter</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(4)">Edit</button>
        </div>
        <div class="card-body">
            <p style="white-space: pre-wrap;">@CoverLetter</p>
        </div>
    </div>

    <div class="d-flex justify-content-between">
        <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@_isSubmitting">
            @if (_isSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                <text>Submitting…</text>
            }
            else
            {
                <text>Submit Application</text>
            }
        </button>
    </div>
}

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEdit { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private bool _isSubmitting;
