@page "/apply"
@using sv_f2ec9f5cdc234ccf89c46c1cb26694a6.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-1">Job Application</h2>
    <p class="text-muted mb-4">Complete all steps to submit your application.</p>

    <StepIndicator CurrentStep="_currentStep" OnStepSelected="GoToStep" />

    <div class="mt-4">
        @switch (_currentStep)
        {
            case 1:
                <PersonalInfoStep Model="_personalInfo"
                                  ApplicationService="_applicationService"
                                  OnNext="NextStep" />
                break;
            case 2:
                <WorkHistoryStep Entries="_workEntries"
                                 OnNext="NextStep"
                                 OnBack="PrevStep" />
                break;
            case 3:
                <ReferencesStep References="_references"
                                OnNext="NextStep"
                                OnBack="PrevStep" />
                break;
            case 4:
                <CoverLetterStep @bind-CoverLetter="_coverLetter"
                                 OnNext="NextStep"
                                 OnBack="PrevStep" />
                break;
            case 5:
                <ReviewStep Personal="_personalInfo"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="_coverLetter"
                            ApplicationService="_applicationService"
                            OnBack="PrevStep"
                            OnEdit="GoToStep" />
                break;
        }
    </div>
</div>

@code {
    [Inject] private IApplicationService _applicationService { get; set; } = default!;

    private int _currentStep = 1;

    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = [new()];
    private readonly List<ReferenceModel> _references = [new(), new()];
    private string _coverLetter = "";

    private void NextStep() => _currentStep++;
    private void PrevStep() => _currentStep--;
    private void GoToStep(int step) => _currentStep = step;
}

